<script>
// Render confirmed scanner results in a dedicated layer.  This keeps the
// status card visible even when the scanner repeatedly returns the same face.
(()=>{
  const nativeFetch=window.fetch.bind(window),shown=new Map();
  function showStatusCards(matches){
    const stack=document.getElementById('detected-stack');
    if(!stack)return;
    stack.classList.add('z-20');
    const now=Date.now();
    matches.forEach(match=>{
      const student=match.student||{},id=String(student.STUDENT_ID||'');
      if(!id)return;
      const state=match.logged?'recorded':'already-logged',previous=shown.get(id);
      if(previous&&previous.state===state&&previous.until>now)return;
      shown.set(id,{state,until:now+5000});
      const card=document.createElement('div');
      card.className='flex w-72 translate-y-2 items-center gap-3 rounded-2xl bg-black/75 p-3 text-left text-white opacity-0 shadow-2xl ring-1 ring-white/20 backdrop-blur transition-all duration-500';
      const image=document.createElement('img');
      image.className='h-12 w-12 rounded-xl object-cover';
      image.src='../'+(student.IMAGE_PATH||'image/student-preview.png');
      image.alt='';
      const text=document.createElement('div');
      text.innerHTML='<p class="text-xs font-bold uppercase tracking-widest text-blue-200"></p><p class="mt-1 text-base font-black"></p><p class="mt-0.5 text-xs text-slate-200"></p>';
      text.querySelector('p:first-child').textContent='Face detected';
      text.querySelector('p:nth-child(2)').textContent=student.STUDENT_NAME||'Student';
      text.querySelector('p:nth-child(3)').textContent=match.logged?'Attendance recorded':'Already logged';
      card.append(image,text);
      stack.appendChild(card);
      requestAnimationFrame(()=>card.classList.remove('translate-y-2','opacity-0'));
      setTimeout(()=>card.classList.add('translate-y-2','opacity-0'),4000);
      setTimeout(()=>card.remove(),4600);
    });
  }
  window.fetch=async(...args)=>{
    const requestBody=args[1]?.body;
    const submittedFrame=requestBody instanceof FormData?requestBody.get('frame'):'';
    const response=await nativeFetch(...args);
    const url=String(args[0] instanceof Request?args[0].url:args[0]);
    if(!url.includes('scan-match.php'))return response;
    try{
      const payload=await response.clone().json();
      window.handleUnregisteredFaces?.(payload.unregistered||[],submittedFrame);
      if(!payload.matches?.length)return response;
      showStatusCards(payload.matches);
      // Let the existing scanner continue drawing face outlines, but prevent
      // its older card renderer from creating duplicate notifications.
      payload.matches=[];
      return new Response(JSON.stringify(payload),{status:response.status,statusText:response.statusText,headers:{'Content-Type':'application/json'}});
    }catch(error){return response;}
  };
})();
</script>
<script>
const unknownTracks=[],unknownCsrf=<?= json_encode($_SESSION['csrf_token']) ?>;
let unknownCount=0,unknownSummaryTimer=null;
function overlap(a,b){const left=Math.max(a.left,b.left),top=Math.max(a.top,b.top),right=Math.min(a.right,b.right),bottom=Math.min(a.bottom,b.bottom),intersection=Math.max(0,right-left)*Math.max(0,bottom-top),areaA=Math.max(1,(a.right-a.left)*(a.bottom-a.top)),areaB=Math.max(1,(b.right-b.left)*(b.bottom-b.top));return intersection/(areaA+areaB-intersection)}
function showUnknownSummary(count){const stack=document.getElementById('detected-stack');if(!stack)return;const card=document.createElement('div');card.className='w-80 translate-y-2 rounded-2xl border border-amber-300/50 bg-amber-950/90 p-4 text-white opacity-0 shadow-2xl backdrop-blur transition-all duration-500';card.innerHTML='<p class="text-xs font-bold uppercase tracking-widest text-amber-200">Unregistered visitor alert</p><p class="mt-1 text-lg font-black"></p><p class="mt-1 text-xs text-amber-100">Face captures were saved for administrator review.</p>';card.querySelector('p:nth-child(2)').textContent=`${count} unregistered ${count===1?'student has':'students have'} entered in the last 30 seconds.`;stack.appendChild(card);requestAnimationFrame(()=>card.classList.remove('translate-y-2','opacity-0'));setTimeout(()=>card.classList.add('translate-y-2','opacity-0'),7000);setTimeout(()=>card.remove(),7600)}
function queueUnknownSummary(){unknownCount++;if(unknownSummaryTimer)return;unknownSummaryTimer=setTimeout(()=>{showUnknownSummary(unknownCount);unknownCount=0;unknownSummaryTimer=null},30000)}
async function saveUnknownFace(box,frame){if(!frame)return;const form=new FormData();form.append('csrf_token',unknownCsrf);form.append('frame',frame);form.append('box',JSON.stringify(box));try{const response=await fetch('log-unregistered.php',{method:'POST',body:form});const result=await response.json();if(result.saved)queueUnknownSummary()}catch(error){console.error('Could not save unregistered face.',error)}}
// A single blurred or backlit frame must never create an unregistered alert.
// Save only a face that remains unrecognized in several consecutive scans.
window.handleUnregisteredFaces=(faces,frame)=>{const now=Date.now();for(let index=unknownTracks.length-1;index>=0;index--)if(now-unknownTracks[index].lastSeen>3000)unknownTracks.splice(index,1);faces.forEach(face=>{const box=face.box;if(!box)return;let track=unknownTracks.find(item=>overlap(item.box,box)>=.35);if(!track){unknownTracks.push({box,lastSeen:now,firstSeen:now,hits:1,saved:false});return}track.box=box;track.lastSeen=now;track.hits++;if(!track.saved&&track.hits>=7&&now-track.firstSeen>=1200){track.saved=true;saveUnknownFace(box,frame)}})};
</script>
<main id="scanner" class="fixed inset-0 overflow-hidden bg-black"><video id="scanner-video" class="h-full w-full object-cover" autoplay muted playsinline></video><canvas id="face-overlay" class="pointer-events-none absolute inset-0 h-full w-full"></canvas><canvas id="scanner-canvas" class="hidden"></canvas><div class="absolute bottom-5 left-5 rounded-xl bg-black/45 px-4 py-3 text-sm font-bold uppercase tracking-widest text-white backdrop-blur">Live attendance scanner</div><div id="detected-stack" class="pointer-events-none absolute bottom-5 right-5 flex max-w-sm flex-col items-end gap-3"></div><div id="scanner-controls" class="absolute inset-x-0 bottom-5 z-10 flex justify-center px-5"><div class="flex items-center gap-3 rounded-2xl bg-black/55 p-3 shadow-2xl backdrop-blur"><button id="scan-toggle" class="inline-flex items-center gap-2 rounded-xl bg-blue-600 px-4 py-3 font-bold text-white hover:bg-blue-700"><span aria-hidden="true">&#9654;</span> Start scanner</button><button id="manual-attendance" class="inline-flex items-center gap-2 rounded-xl bg-white/15 px-4 py-3 font-bold text-white hover:bg-white/25"><span aria-hidden="true">&#9998;</span> Manual attendance</button></div></div><button id="back-button" class="absolute left-5 top-5 z-20 rounded-xl border border-white/30 bg-black/30 px-4 py-3 font-bold text-white backdrop-blur hover:bg-black/55"><span aria-hidden="true">&#8592;</span> Back</button><div id="manual-modal" class="absolute inset-0 z-30 hidden items-center justify-center bg-black/70 p-5"><div class="w-full max-w-sm rounded-2xl bg-white p-6 text-slate-800 shadow-2xl"><div class="flex items-start justify-between gap-3"><div><h1 class="text-xl font-black">Manual attendance</h1><p class="mt-1 text-sm text-slate-500">Search for a student by name.</p></div><button id="close-manual" class="rounded-lg px-2 text-2xl text-slate-400 hover:text-slate-700" aria-label="Close">&times;</button></div><div class="relative mt-5"><input id="manual-student-name" class="w-full rounded-xl border border-slate-300 px-4 py-3" placeholder="Student name" autocomplete="off" autofocus><div id="manual-options" class="absolute inset-x-0 z-10 mt-2 hidden max-h-52 overflow-y-auto rounded-xl border border-slate-200 bg-white p-1 shadow-xl"></div></div><p id="manual-message" class="mt-3 text-sm text-slate-500"></p><div id="manual-result" class="mt-5 hidden text-center"><img id="manual-image" class="mx-auto aspect-square w-48 rounded-2xl object-cover" alt="Student"><p id="manual-name" class="mt-3 text-lg font-black"></p><p id="manual-id-label" class="text-sm text-slate-500"></p><button id="mark-present" class="mt-5 w-full rounded-xl bg-emerald-600 px-4 py-3 font-bold text-white hover:bg-emerald-700">Present</button></div></div></div><div id="exit-modal" class="absolute inset-0 z-40 hidden items-center justify-center bg-black/70 p-5"><form action="scanner-exit.php" method="post" class="w-full max-w-sm rounded-2xl bg-white p-6 text-slate-800 shadow-2xl"><input type="hidden" name="csrf_token" value="<?= htmlspecialchars($_SESSION['csrf_token']) ?>"><h1 class="text-xl font-black">Exit scanner</h1><p class="mt-2 text-sm text-slate-500">Enter the administrator password to return to the dashboard.</p><label class="mt-5 block text-sm font-bold">Password<input id="exit-password" class="mt-2 w-full rounded-xl border border-slate-300 px-4 py-3" type="password" name="password" required></label><div class="mt-5 flex gap-3"><button class="flex-1 rounded-xl bg-blue-600 px-4 py-3 font-bold text-white">Confirm exit</button><button id="cancel-exit" type="button" class="rounded-xl border border-slate-300 px-4 py-3 font-bold">Cancel</button></div></form></div></main>
<script>const video=document.getElementById('scanner-video'),canvas=document.getElementById('scanner-canvas'),faceOverlay=document.getElementById('face-overlay'),detectedStack=document.getElementById('detected-stack'),controls=document.getElementById('scanner-controls'),toggleButton=document.getElementById('scan-toggle'),requestedCamera=<?= json_encode($requestedCamera) ?>,csrfToken=<?= json_encode($_SESSION['csrf_token']) ?>;let stream=null,scanTimer=null,running=false,hideTimer=null,manualStudent=null,searchTimer=null;const recentlyShown=new Map;function showControls(){controls.classList.remove('scanner-controls-hidden');clearTimeout(hideTimer);hideTimer=setTimeout(()=>controls.classList.add('scanner-controls-hidden'),3000)}function renderToggle(){toggleButton.className='inline-flex items-center gap-2 rounded-xl px-4 py-3 font-bold text-white '+(running?'bg-red-600 hover:bg-red-700':'bg-blue-600 hover:bg-blue-700');toggleButton.innerHTML=running?'<span aria-hidden="true">&#9632;</span> Stop scanner':'<span aria-hidden="true">&#9654;</span> Start scanner'}function stop(){running=false;clearTimeout(scanTimer);if(stream){stream.getTracks().forEach(t=>t.stop());stream=null}video.srcObject=null;faceOverlay.getContext('2d').clearRect(0,0,faceOverlay.width,faceOverlay.height);renderToggle()}async function start(){stop();try{const deviceId=requestedCamera||localStorage.getItem('attendance-camera')||'';stream=await navigator.mediaDevices.getUserMedia({video:{deviceId:deviceId?{exact:deviceId}:undefined,width:{ideal:640},height:{ideal:480},frameRate:{ideal:30}},audio:false});video.srcObject=stream;await video.play();running=true;renderToggle();scan()}catch(e){console.error('Unable to open the selected camera.',e);renderToggle()}}function drawFaces(faces){const width=video.clientWidth,height=video.clientHeight,ctx=faceOverlay.getContext('2d');faceOverlay.width=width;faceOverlay.height=height;ctx.clearRect(0,0,width,height);if(!faces?.length||!video.videoWidth)return;const scale=Math.max(width/video.videoWidth,height/video.videoHeight),offsetX=(width-video.videoWidth*scale)/2,offsetY=(height-video.videoHeight*scale)/2;ctx.strokeStyle='#fff';ctx.lineWidth=3;ctx.shadowColor='rgba(0,0,0,.75)';ctx.shadowBlur=5;faces.forEach(face=>{const box=face.box,x=box.left/canvas.width*video.videoWidth*scale+offsetX,y=box.top/canvas.height*video.videoHeight*scale+offsetY,w=(box.right-box.left)/canvas.width*video.videoWidth*scale,h=(box.bottom-box.top)/canvas.height*video.videoHeight*scale,corner=Math.min(26,w/3,h/3);ctx.beginPath();ctx.moveTo(x+corner,y);ctx.lineTo(x,y);ctx.lineTo(x,y+corner);ctx.moveTo(x+w-corner,y);ctx.lineTo(x+w,y);ctx.lineTo(x+w,y+corner);ctx.moveTo(x,y+h-corner);ctx.lineTo(x,y+h);ctx.lineTo(x+corner,y+h);ctx.moveTo(x+w-corner,y+h);ctx.lineTo(x+w,y+h);ctx.lineTo(x+w,y+h-corner);ctx.stroke()});ctx.shadowBlur=0}function showMatches(matches){const now=Date.now();matches.forEach(match=>{const id=match.student.STUDENT_ID;if((recentlyShown.get(id)||0)>now)return;recentlyShown.set(id,now+5000);const card=document.createElement('div');card.className='flex w-72 translate-y-2 items-center gap-3 rounded-2xl bg-black/55 p-3 text-left text-white opacity-0 shadow-2xl backdrop-blur transition-all duration-500';const image=document.createElement('img');image.className='h-12 w-12 rounded-xl object-cover';image.src='../'+(match.student.IMAGE_PATH||'image/student-preview.png');image.alt='';const text=document.createElement('div');text.innerHTML='<p class="text-xs font-bold uppercase tracking-widest text-blue-200"></p><p class="mt-1 text-base font-black"></p><p class="mt-0.5 text-xs text-slate-200"></p>';text.querySelector('p:first-child').textContent=match.manual?'Manual attendance':'Face detected';text.querySelector('p:nth-child(2)').textContent=match.student.STUDENT_NAME;text.querySelector('p:nth-child(3)').textContent=match.logged?'Attendance recorded':'Already logged';card.append(image,text);detectedStack.appendChild(card);requestAnimationFrame(()=>card.classList.remove('translate-y-2','opacity-0'));setTimeout(()=>card.classList.add('translate-y-2','opacity-0'),4000);setTimeout(()=>card.remove(),4600)})}async function scan(){if(!running||!stream||video.readyState<2)return;const scale=Math.min(1,560/video.videoWidth);canvas.width=Math.round(video.videoWidth*scale);canvas.height=Math.round(video.videoHeight*scale);canvas.getContext('2d',{alpha:false}).drawImage(video,0,0,canvas.width,canvas.height);try{const form=new FormData();form.append('frame',canvas.toDataURL('image/jpeg',.65));const response=await fetch('scan-match.php',{method:'POST',body:form});const result=await response.json();drawFaces(result.faces||[]);if(result.matches?.length)showMatches(result.matches)}catch(e){console.error('Recognition service unavailable.',e)}finally{if(running)scanTimer=setTimeout(scan,180)}}async function selectStudent(id){const message=document.getElementById('manual-message'),result=document.getElementById('manual-result'),options=document.getElementById('manual-options');options.classList.add('hidden');message.textContent='Loading student…';result.classList.add('hidden');const response=await fetch('manual-student.php?id='+encodeURIComponent(id));const data=await response.json();if(!data.student){manualStudent=null;message.textContent=data.message||'Student not found.';return}manualStudent=data.student;document.getElementById('manual-image').src='../'+(manualStudent.IMAGE_PATH||'image/student-preview.png');document.getElementById('manual-name').textContent=manualStudent.STUDENT_NAME;document.getElementById('manual-id-label').textContent=manualStudent.STUDENT_ID;document.getElementById('mark-present').textContent=data.already_logged?'Already logged':'Present';document.getElementById('mark-present').disabled=data.already_logged;document.getElementById('mark-present').className='mt-5 w-full rounded-xl px-4 py-3 font-bold text-white '+(data.already_logged?'bg-slate-400':'bg-emerald-600 hover:bg-emerald-700');message.textContent='';result.classList.remove('hidden')}async function searchStudents(){const name=document.getElementById('manual-student-name').value.trim(),options=document.getElementById('manual-options');clearTimeout(searchTimer);if(name.length<2){options.classList.add('hidden');return}searchTimer=setTimeout(async()=>{const response=await fetch('manual-students-search.php?q='+encodeURIComponent(name));const data=await response.json();options.innerHTML='';(data.students||[]).forEach(student=>{const button=document.createElement('button');button.type='button';button.className='flex w-full items-center gap-3 rounded-lg px-3 py-3 text-left hover:bg-slate-100';button.innerHTML='<img class="h-10 w-10 rounded-lg object-cover" alt=""><span><span class="block font-bold"></span><span class="block text-xs text-slate-500"></span></span>';button.querySelector('img').src='../'+(student.IMAGE_PATH||'image/student-preview.png');button.querySelector('span span:first-child').textContent=student.STUDENT_NAME;button.querySelector('span span:last-child').textContent=student.STUDENT_ID;button.onclick=()=>{document.getElementById('manual-student-name').value=student.STUDENT_NAME;selectStudent(student.STUDENT_ID)};options.appendChild(button)});options.classList.toggle('hidden',!options.children.length)},250)}async function markPresent(){if(!manualStudent)return;const form=new FormData();form.append('student_id',manualStudent.STUDENT_ID);form.append('csrf_token',csrfToken);const response=await fetch('manual-attendance-save.php',{method:'POST',body:form});const data=await response.json();if(data.student){document.getElementById('manual-modal').classList.replace('flex','hidden');showMatches([{student:data.student,logged:data.logged,manual:true}])}else document.getElementById('manual-message').textContent=data.message||'Could not record attendance.'}toggleButton.onclick=()=>running?stop():start();document.getElementById('manual-attendance').onclick=()=>{document.getElementById('manual-modal').classList.replace('hidden','flex');setTimeout(()=>document.getElementById('manual-student-name').focus(),0);showControls()};document.getElementById('close-manual').onclick=()=>document.getElementById('manual-modal').classList.replace('flex','hidden');document.getElementById('manual-student-name').oninput=searchStudents;document.getElementById('mark-present').onclick=markPresent;document.getElementById('back-button').onclick=()=>{document.getElementById('exit-modal').classList.replace('hidden','flex');setTimeout(()=>document.getElementById('exit-password').focus(),0)};document.getElementById('cancel-exit').onclick=()=>document.getElementById('exit-modal').classList.replace('flex','hidden');document.addEventListener('mousemove',showControls);document.addEventListener('touchstart',showControls,{passive:true});window.addEventListener('beforeunload',stop);renderToggle();showControls();</script></body></html>
